        'gh workflow run machine-sm.yml -R "\$GITHUB_REPOSITORY" '
        '-f dryRun=false',
        isIn(kicker),
        reason:
            'the sm-kicker rescue tick must dispatch a LIVE tick — this exact '
            'line is what un-sticks the SM after a missed cron window',
